// ============================================================
// NOTIFICATION HOOK
// ============================================================
const useSimpleNotification = () => {
  const [notification, setNotification] = useState(null);
  const timerRef = useRef(null);

  const clearNotification = useCallback(() => {
    if (timerRef.current) clearTimeout(timerRef.current);
    timerRef.current = null;
    setNotification(null);
  }, []);

  const showNotification = useCallback((message, type = 'info') => {
    // a new message replaces the old one and gets its own full display time
    if (timerRef.current) clearTimeout(timerRef.current);
    setNotification({ message, type });
    timerRef.current = setTimeout(() => setNotification(null), type === 'error' ? 6000 : 3000);
  }, []);

  useEffect(() => () => timerRef.current && clearTimeout(timerRef.current), []);

  return { notification, showNotification, clearNotification };
};

// Builds the /api/trips query params from the screen filters (shared by list + export)
const buildListParams = ({ search, status, city, customer }) => {
  const params = {};
  if (status && status !== 'all' && status !== 'undefined') params.status = status;
  if (search) params.search = search;
  if (city) params.city = city;
  if (customer) params.customer = customer;
  return params;
};

// ============================================================
// MAIN COMPONENT
// ============================================================
function TripList() {
  const { notification, showNotification, clearNotification } = useSimpleNotification();
  
  const [trips, setTrips] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [searchText, setSearchText] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');
  const [cityFilter, setCityFilter] = useState('');
  const [customerFilter, setCustomerFilter] = useState('');
  const [selectedTrip, setSelectedTrip] = useState(null);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [showMetricsModal, setShowMetricsModal] = useState(false);
  const [showDetailsModal, setShowDetailsModal] = useState(false);
  const [showNoticeWizard, setShowNoticeWizard] = useState(false);
  const [selectedTripForNotice, setSelectedTripForNotice] = useState(null);
  const [pagination, setPagination] = useState({ page: 0, pageSize: 10, total: 0 });
  
  // Delete Dialog
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [deleteTarget, setDeleteTarget] = useState(null);
  const [deleting, setDeleting] = useState(false);

  // Cancel Dialog
  const [cancelTarget, setCancelTarget] = useState(null);
  const [cancelling, setCancelling] = useState(false);
  
  // End Trip Dialog
  const [endDialogOpen, setEndDialogOpen] = useState(false);
  const [endTripId, setEndTripId] = useState(null);
  const [endOdometer, setEndOdometer] = useState('');
  const [endTripDetails, setEndTripDetails] = useState(null);
  const [endingTrip, setEndingTrip] = useState(false);

  // Metrics cache for performance
  const metricsCache = useRef({});
  const fetchTimerRef = useRef(null);
  const skipFirstDebounce = useRef(true);

  const uniqueCities = useMemo(
    () => [...new Set(trips.map(t => t.originCity).filter(Boolean))],
    [trips]
  );

  const uniqueCustomers = useMemo(
    () => [...new Set(trips.map(t => t.customer?.name || t.customerName).filter(Boolean))],
    [trips]
  );

  // ============================================================
  // FETCH TRIPS
  // ============================================================
  const fetchTrips = useCallback(async ({ 
    page = 0, 
    size = pagination.pageSize, 
    search = searchText, 
    status = statusFilter, 
    city = cityFilter, 
    customer = customerFilter 
  } = {}) => {
    setLoading(true);
    setError(null);
    try {
      const params = {
        page: Number(page),
        size: Number(size),
        sort: 'id,desc',
        ...buildListParams({ search, status, city, customer }),
      };

      console.log('📤 Fetching trips with params:', params);

      const response = await tripService.getAllTrips(params);
      
      console.log('📥 Response:', {
        page: response.number,
        totalElements: response.totalElements,
        totalPages: response.totalPages,
        contentLength: response.content?.length
      });

      // Fetch metrics for each trip with caching
      const tripsWithMetrics = await Promise.all(
        (response.content || []).map(async (trip) => {
          if (metricsCache.current[trip.id]) {
            return { ...trip, metrics: metricsCache.current[trip.id] };
          }
          try {
            const metrics = await tripService.getTripMetrics(trip.id);
            metricsCache.current[trip.id] = metrics;
            return { ...trip, metrics };
          } catch {
            metricsCache.current[trip.id] = null;
            return { ...trip, metrics: null };
          }
        })
      );

      if (tripsWithMetrics.length > 0) {
        console.log('🔍 First trip with metrics:', {
          id: tripsWithMetrics[0].id,
          plannedDistance: tripsWithMetrics[0].plannedDistanceKm,
          actualDistance: tripsWithMetrics[0].metrics?.totalDistanceKm,
          hasMetrics: !!tripsWithMetrics[0].metrics
        });
      }

      setTrips(tripsWithMetrics);
      setPagination({
        page: response.number ?? page,
        pageSize: response.size ?? size,
        total: response.totalElements ?? 0
      });
    } catch (err) {
      console.error('Error fetching trips:', err);
      setError(err.message || 'Failed to load trips');
      showNotification('Failed to load trips', 'error');
      setTrips([]);
    } finally {
      setLoading(false);
    }
  }, [pagination.pageSize, searchText, statusFilter, cityFilter, customerFilter, showNotification]);

  // Initial fetch
  useEffect(() => {
    fetchTrips({ page: 0, status: 'all' });
  }, []);

  // Debounced filter changes (skipped on mount - the initial fetch above already ran)
  useEffect(() => {
    if (skipFirstDebounce.current) {
      skipFirstDebounce.current = false;
      return undefined;
    }
    if (fetchTimerRef.current) clearTimeout(fetchTimerRef.current);
    fetchTimerRef.current = setTimeout(() => fetchTrips({ page: 0 }), 400);
    return () => clearTimeout(fetchTimerRef.current);
  }, [searchText, statusFilter, cityFilter, customerFilter]);

  // ============================================================
  // ACTION HANDLERS
  // ============================================================

  const handleStartTrip = (trip) => {
    if (!window.confirm(`Start trip #${trip.tripNumber}?`)) return;
    
    const startOdometer = prompt('Enter starting odometer reading (km):');
    if (startOdometer === null || startOdometer.trim() === '') return;
    const startOdo = parseFloat(startOdometer.replace(',', '.'));
    if (!Number.isFinite(startOdo) || startOdo < 0) {
      showNotification('Please enter a valid odometer reading (number of km).', 'error');
      return;
    }

    tripService.startTrip(trip.id, { actualStartOdometer: startOdo })
      .then(() => {
        showNotification('Trip started successfully!', 'success');
        metricsCache.current = {};
        fetchTrips({ page: pagination.page });
      })
      .catch(err => {
        console.error('Error starting trip:', err);
        showNotification(err.userMessage || err.message || 'Failed to start trip', 'error');
      });
  };

  // ============================================================
  // END TRIP - FIXED with proper dialog
  // ============================================================
  
  const handleOpenEndDialog = async (trip) => {
    try {
      // Fetch trip details to get start odometer
      const tripDetails = await tripService.getTripById(trip.id);
      setEndTripId(trip.id);
      setEndTripDetails(tripDetails);
      setEndOdometer('');
      setEndDialogOpen(true);
      setError(null);
    } catch (err) {
      console.error('Error fetching trip details:', err);
      showNotification('Failed to load trip details', 'error');
    }
  };

  const handleCloseEndDialog = () => {
    setEndDialogOpen(false);
    setEndTripId(null);
    setEndTripDetails(null);
    setEndOdometer('');
    setError(null);
  };

  const handleEndTripConfirm = async () => {
    if (!endTripId || !endTripDetails) return;

    const endOdometerNum = parseFloat(endOdometer);
    
    // Validate input
    if (isNaN(endOdometerNum) || endOdometerNum <= 0) {
      setError('Please enter a valid odometer reading (positive number).');
      return;
    }
    
    // Validate against start odometer
    const startOdometer = endTripDetails.actualStartOdometer;
    if (startOdometer && endOdometerNum < startOdometer) {
      setError(
        `❌ End odometer (${endOdometerNum.toFixed(2)} km) cannot be less than start odometer (${startOdometer.toFixed(2)} km).\n\nPlease enter a valid ending odometer reading.`
      );
      return;
    }

    setEndingTrip(true);
    setError(null);

    try {
      await tripService.endTrip(endTripId, endOdometerNum);
      showNotification('Trip ended successfully!', 'success');
      handleCloseEndDialog();
      metricsCache.current = {};
      fetchTrips({ page: pagination.page });
    } catch (err) {
      console.error('Error ending trip:', err);
      let errorMessage = err.message || 'Failed to end trip';
      if (err.response?.data?.detail) {
        const detail = err.response.data.detail;
        if (detail.includes('cannot be less than start odometer')) {
          errorMessage = '❌ End odometer cannot be less than start odometer. Please check the reading.';
        } else {
          errorMessage = detail;
        }
      }
      setError(errorMessage);
    } finally {
      setEndingTrip(false);
    }
  };

  const handleOpenNoticeWizard = (trip) => {
    setSelectedTripForNotice(trip);
    setShowNoticeWizard(true);
  };

  const handleCloseNoticeWizard = () => {
    setShowNoticeWizard(false);
    setSelectedTripForNotice(null);
    fetchTrips({ page: pagination.page });
  };

  const handleMetricsSuccess = () => {
    console.log('🔄 Metrics updated, refreshing trip list...');
    setShowMetricsModal(false);
    metricsCache.current = {};
    setTimeout(() => {
      fetchTrips({ page: pagination.page });
      showNotification('Trip metrics updated successfully!', 'success');
    }, 500);
  };
  
  const handleViewTrip = (trip) => {
    setSelectedTrip(trip);
    setShowDetailsModal(true);
  };

  const handleEditTrip = (trip) => {
    setSelectedTrip(trip);
    setShowEditModal(true);
  };

  const handleOpenMetrics = (trip) => {
    console.log('📊 Opening metrics for trip:', trip.id);
    setSelectedTrip(trip);
    setShowMetricsModal(true);
  };

  const handleFinalizeTrip = async (trip) => {
    if (!window.confirm('Are you sure you want to finalize this trip?')) return;
    
    try {
      await tripService.finalizeTrip(trip.id);
      showNotification('Trip finalized successfully!', 'success');
      metricsCache.current = {};
      fetchTrips({ page: pagination.page });
    } catch (err) {
      console.error('Error finalizing trip:', err);
      showNotification(err.userMessage || err.message || 'Failed to finalize trip', 'error');
    }
  };

  const handleDeleteClick = (trip) => {
    setDeleteTarget(trip);
    setDeleteDialogOpen(true);
  };

  const handleDeleteConfirm = async () => {
    if (!deleteTarget) return;
    setDeleting(true);
    try {
      await tripService.deleteTrip(deleteTarget.id);
      setDeleteDialogOpen(false);
      setDeleteTarget(null);
      showNotification(`Trip ${deleteTarget.tripNumber || ''} deleted`, 'success');
      metricsCache.current = {};
      fetchTrips({ page: 0 });
    } catch (err) {
      console.error('Error deleting trip:', err);
      // show the server's reason (e.g. status does not allow delete / no permission)
      showNotification(err.userMessage || err.message || 'Failed to delete trip', 'error');
    } finally {
      setDeleting(false);
    }
  };

  const handleDeleteCancel = () => {
    setDeleteDialogOpen(false);
    setDeleteTarget(null);
  };

  const handleCancelTripConfirm = async () => {
    if (!cancelTarget) return;
    setCancelling(true);
    try {
      await tripService.cancelTrip(cancelTarget.id);
      showNotification(`Trip ${cancelTarget.tripNumber || ''} cancelled`, 'success');
      setCancelTarget(null);
      metricsCache.current = {};
      fetchTrips({ page: pagination.page });
    } catch (err) {
      console.error('Error cancelling trip:', err);
      showNotification(err.userMessage || err.message || 'Failed to cancel trip', 'error');
    } finally {
      setCancelling(false);
    }
  };

  const handleClearFilters = () => {
    setSearchText('');
    setStatusFilter('all');
    setCityFilter('');
    setCustomerFilter('');
  };

  const handleModalClose = (callback) => () => {
    callback();
    setTimeout(() => {
      metricsCache.current = {};
      fetchTrips({ page: pagination.page });
    }, 300);
  };

  const getTripDisplay = (trip) => {
    let driverName = 'N/A';
    
    if (trip.driver) {
      if (trip.driver.firstName || trip.driver.lastName) {
        driverName = `${trip.driver.firstName || ''} ${trip.driver.lastName || ''}`.trim();
      } else if (trip.driver.name) {
        driverName = trip.driver.name;
      } else if (trip.driver.fullName) {
        driverName = trip.driver.fullName;
      } else if (typeof trip.driver === 'string') {
        driverName = trip.driver;
      }
    }
    
    if (driverName === 'N/A' || !driverName) {
      driverName = trip.driverName || trip.driver_name || trip.assignedDriver || 'N/A';
    }

    return {
      customerName: trip.customer?.name || trip.customerName || 'N/A',
      vehicleReg: trip.vehicle?.registrationNumber || trip.vehicleRegistration || 'N/A',
      driverName: driverName,
      canStart: STATUS_KEYS.CAN_START.includes(trip.status),
      canEnd: STATUS_KEYS.CAN_END.includes(trip.status),
      canReport: STATUS_KEYS.CAN_REPORT_INCIDENT.includes(trip.status),
      canFinalize: STATUS_KEYS.CAN_FINALIZE.includes(trip.status),
      canEdit: STATUS_KEYS.CAN_EDIT.includes(trip.status),
      canDelete: STATUS_KEYS.CAN_DELETE.includes(trip.status),
      canCancel: STATUS_KEYS.CAN_CANCEL.includes(trip.status),
      canMetrics: STATUS_KEYS.CAN_METRICS.includes(trip.status),
    };
  };

  // ============================================================
  // EXPORT (all trips matching the current filters, not just this page)
  // ============================================================
  const toNum = (v) => {
    if (v === null || v === undefined || v === '') return null;
    const n = Number(v);
    return Number.isFinite(n) ? n : null;
  };
  const fmtDate = (d) => (d ? dayjs(d).format('YYYY-MM-DD') : '');

  const exportColumns = [
    { header: 'Trip #', value: (t) => t.tripNumber, width: 14 },
    { header: 'Reference', value: (t) => t.referenceNumber, width: 14 },
    { header: 'Status', value: (t) => STATUS_CONFIG[t.status]?.label || t.status, width: 14 },
    { header: 'Customer', value: (t) => getTripDisplay(t).customerName, width: 24 },
    { header: 'Vehicle', value: (t) => getTripDisplay(t).vehicleReg, width: 14 },
    { header: 'Driver', value: (t) => getTripDisplay(t).driverName, width: 20 },
    { header: 'Origin City', value: (t) => t.originCity, width: 16 },
    { header: 'Origin Address', value: (t) => t.originLocation, width: 30 },
    { header: 'Destination City', value: (t) => t.destinationCity, width: 16 },
    { header: 'Destination Address', value: (t) => t.destinationLocation, width: 30 },
    { header: 'Planned Distance (km)', value: (t) => toNum(t.plannedDistanceKm), type: 'number', decimals: 1 },
    {
      header: 'Actual Distance (km)',
      value: (t) => toNum(metricsCache.current[t.id]?.totalDistanceKm ?? t.totalDistanceKm),
      type: 'number',
      decimals: 1,
    },
    { header: 'Planned Start', value: (t) => fmtDate(t.plannedStartDate), width: 12 },
    { header: 'Planned End', value: (t) => fmtDate(t.plannedEndDate), width: 12 },
    { header: 'Start Odometer', value: (t) => toNum(t.actualStartOdometer), type: 'number', decimals: 1 },
    { header: 'End Odometer', value: (t) => toNum(t.actualEndOdometer), type: 'number', decimals: 1 },
  ];

  const exportSubtitle = [
    statusFilter !== 'all' && `Status: ${STATUS_CONFIG[statusFilter]?.label || statusFilter}`,
    searchText && `Search: "${searchText}"`,
    cityFilter && `City: ${cityFilter}`,
    customerFilter && `Customer: ${customerFilter}`,
    `Exported ${dayjs().format('YYYY-MM-DD HH:mm')}`,
  ]
    .filter(Boolean)
    .join('  •  ');

  const fetchExportRows = () =>
    tripService.fetchAllTrips(
      buildListParams({ search: searchText, status: statusFilter, city: cityFilter, customer: customerFilter })
    );

  const getTripCounts = useMemo(() => {
    const counts = { total: trips.length };
    trips.forEach(t => {
      counts[t.status] = (counts[t.status] || 0) + 1;
    });
    return counts;
  }, [trips]);

  // ============================================================
  // RENDER
  // ============================================================
  
  if (loading && trips.length === 0) {
    return (
      <Box sx={{ 
        bgcolor: '#F7F7FC', 
        minHeight: '100vh',
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center'
      }}>
        <CircularProgress size={40} />
        <Typography sx={{ ml: 2, fontSize: '0.9rem' }}>Loading trips...</Typography>
      </Box>
    );
  }

  return (
    <Box sx={{ 
      bgcolor: '#F7F7FC', 
      minHeight: '100vh',
      height: '100%',
      display: 'flex',
      flexDirection: 'column',
      p: { xs: 1.5, sm: 2, md: 2.5, lg: 3 },
      width: '100%',
      overflowX: 'hidden' 
    }}>
      <Box sx={{ 
        maxWidth: '1600px', 
        margin: '0 auto',
        flex: 1,
        width: '100%',
        display: 'flex',
        flexDirection: 'column',
      }}>
        
        {/* Notification */}
        {notification && (
          <Alert 
            severity={notification.type} 
            sx={{ mb: 2, borderRadius: '12px', fontSize: '0.8rem' }}
            onClose={clearNotification}
          >
            {notification.message}
          </Alert>
        )}

        {/* Error Alert */}
        {error && (
          <Alert 
            severity="error" 
            sx={{ mb: 2, borderRadius: '12px', fontSize: '0.8rem', whiteSpace: 'pre-line' }}
            onClose={() => setError(null)}
          >
            {error}
          </Alert>
        )}

        {/* Header */}
        <Stack
          direction={{ xs: 'column', sm: 'row' }}
          justifyContent="space-between"
          alignItems={{ xs: 'flex-start', sm: 'center' }}
          mb={{ xs: 2, sm: 2.5, md: 3 }}
          spacing={{ xs: 1, sm: 0 }}
        >
          <Box>
            <Typography 
              variant="h5" 
              fontWeight="700" 
              sx={{ 
                fontSize: { 
                  xs: '1.1rem', 
                  sm: '1.3rem', 
                  md: '1.4rem', 
                  lg: '1.5rem' 
                } 
              }}
            >
              Trip Management
            </Typography>
            <Typography 
              variant="body2" 
              color="text.secondary" 
              sx={{ 
                fontSize: { 
                  xs: '0.7rem', 
                  sm: '0.8rem', 
                  md: '0.85rem' 
                } 
              }}
            >
              Manage and track all trips • {pagination.total} total trips
            </Typography>
          </Box>
          <Stack direction="row" spacing={1}>
            <Button
              variant="outlined"
              startIcon={<RefreshIcon sx={{ fontSize: { xs: '0.8rem', sm: '0.9rem' } }} />}
              onClick={() => {
                metricsCache.current = {};
                fetchTrips({ page: pagination.page });
              }}
              size="small"
              sx={{
                borderRadius: '10px',
                fontSize: { xs: '0.7rem', sm: '0.75rem', md: '0.8rem' },
                textTransform: 'none',
                py: { xs: 0.5, sm: 0.75 },
                px: { xs: 1.5, sm: 2 },
              }}
            >
              Refresh
            </Button>
            <ExportButton
              title="Trips"
              columns={exportColumns}
              fetchRows={fetchExportRows}
              subtitle={exportSubtitle}
              disabled={pagination.total === 0}
              onError={(msg) => showNotification(msg, 'error')}
              onSuccess={(msg) => showNotification(msg, 'success')}
            />
            <Button
              variant="contained"
              startIcon={<AddIcon sx={{ fontSize: { xs: '0.8rem', sm: '0.9rem' } }} />}
              onClick={() => setShowCreateModal(true)}
              size="small"
              sx={{
                borderRadius: '10px',
                fontSize: { xs: '0.7rem', sm: '0.75rem', md: '0.8rem' },
                textTransform: 'none',
                py: { xs: 0.5, sm: 0.75 },
                px: { xs: 1.5, sm: 2 },
                background: 'linear-gradient(135deg, #4F46E5 0%, #6366F1 100%)',
                '&:hover': {
                  background: 'linear-gradient(135deg, #4338CA 0%, #4F46E5 100%)',
                },
              }}
            >
              New Trip
            </Button>
          </Stack>
        </Stack>

        {/* Stats Cards */}
        <Grid 
          container 
          spacing={{ xs: 1.5, sm: 2, md: 2.5, lg: 3 }}
          sx={{ 
            mb: { xs: 2, sm: 2.5, md: 3 },
            width: '100%',
            margin: 0,
          }}
        >
          <Grid size={{ xs: 6, sm: 3 }} sx={{ display: 'flex' }}>
            <StatCard
              title="Total Trips"
              value={pagination.total}
              icon={RouteIcon}
              color="primary"
              subtitle="All trips"
            />
          </Grid>
          <Grid size={{ xs: 6, sm: 3 }} sx={{ display: 'flex' }}>
            <StatCard
              title="Active"
              value={getTripCounts.ACTIVE || 0}
              icon={DirectionsCar}
              color="success"
              subtitle="On this page"
            />
          </Grid>
          <Grid size={{ xs: 6, sm: 3 }} sx={{ display: 'flex' }}>
            <StatCard
              title="In Progress"
              value={getTripCounts.IN_PROGRESS || 0}
              icon={PendingIcon}
              color="warning"
              subtitle="On this page"
            />
          </Grid>
          <Grid size={{ xs: 6, sm: 3 }} sx={{ display: 'flex' }}>
            <StatCard
              title="Completed"
              value={getTripCounts.COMPLETED || 0}
              icon={CheckCircleIcon}
              color="purple"
              subtitle="On this page"
            />
          </Grid>
        </Grid>

        {/* Filters */}
        <Paper
          elevation={0}
          sx={{
            p: { xs: 1.5, sm: 2 },
            mb: { xs: 2, sm: 2.5, md: 3 },
            borderRadius: { xs: '12px', sm: '16px' },
            border: '1px solid #ECECEC',
            bgcolor: '#FFFFFF',
            width: '100%',
          }}
        >
          <Stack 
            direction={{ xs: 'column', sm: 'row' }} 
            spacing={{ xs: 1, sm: 1.5 }}
            alignItems={{ xs: 'stretch', sm: 'center' }}
            flexWrap="wrap"
            useFlexGap
          >
            <TextField
              size="small"
              placeholder="Search trips..."
              value={searchText}
              onChange={(e) => setSearchText(e.target.value)}
              sx={{ 
                flex: 1,
                minWidth: { xs: '100%', sm: 200 },
                '& .MuiInputLabel-root': { fontSize: { xs: '0.65rem', sm: '0.75rem' } },
                '& .MuiInputBase-root': { fontSize: { xs: '0.7rem', sm: '0.75rem' }, borderRadius: '10px' },
              }}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <SearchIcon sx={{ fontSize: { xs: '0.8rem', sm: '0.9rem' } }} />
                  </InputAdornment>
                ),
              }}
            />         
            <FormControl size="small" sx={{ minWidth: { xs: '100%', sm: 130 } }}>
              <InputLabel sx={{ fontSize: { xs: '0.65rem', sm: '0.75rem' } }}>Status</InputLabel>
              <Select
                value={statusFilter}
                onChange={(e) => setStatusFilter(e.target.value)}
                label="Status"
                sx={{ fontSize: { xs: '0.7rem', sm: '0.75rem' }, borderRadius: '10px' }}
              >
                <MenuItem value="all" sx={{ fontSize: { xs: '0.7rem', sm: '0.75rem' } }}>All Statuses</MenuItem>
                {TRIP_STATUS_OPTIONS.map(status => (
                  <MenuItem key={status.value} value={status.value} sx={{ fontSize: { xs: '0.7rem', sm: '0.75rem' } }}>
                    {status.label}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>
            {uniqueCities.length > 0 && (
              <FormControl size="small" sx={{ minWidth: { xs: '100%', sm: 140 } }}>
                <InputLabel sx={{ fontSize: { xs: '0.65rem', sm: '0.75rem' } }}>City</InputLabel>
                <Select
                  value={cityFilter}
                  onChange={(e) => setCityFilter(e.target.value)}
                  label="City"
                  sx={{ fontSize: { xs: '0.7rem', sm: '0.75rem' }, borderRadius: '10px' }}
                >
                  <MenuItem value="" sx={{ fontSize: { xs: '0.7rem', sm: '0.75rem' } }}>All Cities</MenuItem>
                  {uniqueCities.map(city => (
                    <MenuItem key={city} value={city} sx={{ fontSize: { xs: '0.7rem', sm: '0.75rem' } }}>{city}</MenuItem>
                  ))}
                </Select>
              </FormControl>
            )}

            {uniqueCustomers.length > 0 && (
              <FormControl size="small" sx={{ minWidth: { xs: '100%', sm: 150 } }}>
                <InputLabel sx={{ fontSize: { xs: '0.65rem', sm: '0.75rem' } }}>Customer</InputLabel>
                <Select
                  value={customerFilter}
                  onChange={(e) => setCustomerFilter(e.target.value)}
                  label="Customer"
                  sx={{ fontSize: { xs: '0.7rem', sm: '0.75rem' }, borderRadius: '10px' }}
                >
                  <MenuItem value="" sx={{ fontSize: { xs: '0.7rem', sm: '0.75rem' } }}>All Customers</MenuItem>
                  {uniqueCustomers.map(customer => (
                    <MenuItem key={customer} value={customer} sx={{ fontSize: { xs: '0.7rem', sm: '0.75rem' } }}>{customer}</MenuItem>
                  ))}
                </Select>
              </FormControl>
            )}

            <Button 
              onClick={handleClearFilters}
              disabled={!searchText && statusFilter === 'all' && !cityFilter && !customerFilter}
              variant="outlined"
              size="small"
              startIcon={<ClearIcon sx={{ fontSize: { xs: '0.8rem', sm: '0.9rem' } }} />}
              sx={{
                borderRadius: '10px',
                fontSize: { xs: '0.7rem', sm: '0.75rem' },
                textTransform: 'none',
                py: { xs: 0.5, sm: 0.75 },
                px: { xs: 1, sm: 1.5 },
              }}
            >
              Clear
            </Button>
          </Stack>
        </Paper>

        {/* Table */}
        <Paper
          elevation={0}
          sx={{
            borderRadius: { xs: '12px', sm: '16px' },
            border: '1px solid #ECECEC',
            bgcolor: '#FFFFFF',
            width: '100%',
            overflow: 'hidden',
          }}
        >
          <TableContainer>
            <Table size="small">
              <TableHead sx={{ bgcolor: '#F9FAFB' }}>
                <TableRow>
                  <TableCell sx={{ fontSize: { xs: '0.6rem', sm: '0.7rem' }, fontWeight: 600, color: '#6B7280', py: 1.5 }}>
                    Trip #
                  </TableCell>
                  <TableCell sx={{ fontSize: { xs: '0.6rem', sm: '0.7rem' }, fontWeight: 600, color: '#6B7280', py: 1.5 }}>
                    Customer
                  </TableCell>
                  <TableCell sx={{ fontSize: { xs: '0.6rem', sm: '0.7rem' }, fontWeight: 600, color: '#6B7280', py: 1.5 }}>
                    Vehicle
                  </TableCell>
                  <TableCell sx={{ fontSize: { xs: '0.6rem', sm: '0.7rem' }, fontWeight: 600, color: '#6B7280', py: 1.5 }}>
                    Driver
                  </TableCell>
                  <TableCell sx={{ fontSize: { xs: '0.6rem', sm: '0.7rem' }, fontWeight: 600, color: '#6B7280', py: 1.5 }}>
                    Status
                  </TableCell>
                  <TableCell sx={{ fontSize: { xs: '0.6rem', sm: '0.7rem' }, fontWeight: 600, color: '#6B7280', py: 1.5 }}>
                    Origin
                  </TableCell>
                  <TableCell sx={{ fontSize: { xs: '0.6rem', sm: '0.7rem' }, fontWeight: 600, color: '#6B7280', py: 1.5 }}>
                    Destination
                  </TableCell>
                  <TableCell sx={{ fontSize: { xs: '0.6rem', sm: '0.7rem' }, fontWeight: 600, color: '#6B7280', py: 1.5 }}>
                    Distance
                  </TableCell>
                  <TableCell sx={{ fontSize: { xs: '0.6rem', sm: '0.7rem' }, fontWeight: 600, color: '#6B7280', py: 1.5 }}>
                    Date
                  </TableCell>
                  <TableCell sx={{ fontSize: { xs: '0.6rem', sm: '0.7rem' }, fontWeight: 600, color: '#6B7280', py: 1.5 }}>
                    Actions
                  </TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {trips.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={10} align="center" sx={{ py: 4 }}>
                      <Box sx={{ textAlign: 'center' }}>
                        <RouteIcon sx={{ fontSize: 48, color: '#D1D5DB', mb: 2 }} />
                        <Typography variant="body1" color="text.secondary">
                          {searchText || statusFilter !== 'all' || cityFilter || customerFilter
                            ? 'No trips match your filters'
                            : 'No trips found'}
                        </Typography>
                        {(searchText || statusFilter !== 'all' || cityFilter || customerFilter) && (
                          <Button onClick={handleClearFilters} sx={{ mt: 1, fontSize: '0.7rem' }} size="small">
                            Clear Filters
                          </Button>
                        )}
                      </Box>
                    </TableCell>
                  </TableRow>
                ) : (
                  trips.map(trip => {
                    const display = getTripDisplay(trip);
                    
                    return (
                      <TableRow key={trip.id} hover sx={{ '&:hover': { bgcolor: '#F9FAFB' } }}>
                        <TableCell sx={{ fontSize: { xs: '0.6rem', sm: '0.7rem' }, py: 1 }}>
                          <Typography fontWeight="600" sx={{ fontSize: { xs: '0.6rem', sm: '0.7rem' }, color: '#4F46E5' }}>
                            {trip.tripNumber}
                          </Typography>
                          {trip.referenceNumber && (
                            <Typography variant="caption" sx={{ fontSize: { xs: '0.5rem', sm: '0.55rem' }, color: '#6B7280', display: 'block' }}>
                              REF: {trip.referenceNumber}
                            </Typography>
                          )}
                        </TableCell>

                        <TableCell sx={{ fontSize: { xs: '0.6rem', sm: '0.7rem' }, py: 1 }}>
                          {display.customerName !== 'N/A' ? (
                            <Typography sx={{ fontSize: { xs: '0.6rem', sm: '0.7rem' } }}>{display.customerName}</Typography>
                          ) : (
                            <Typography color="text.secondary" sx={{ fontSize: { xs: '0.55rem', sm: '0.65rem' } }}>N/A</Typography>
                          )}
                        </TableCell>

                        <TableCell sx={{ fontSize: { xs: '0.6rem', sm: '0.7rem' }, py: 1 }}>
                          {display.vehicleReg !== 'N/A' ? (
                            <Typography sx={{ fontSize: { xs: '0.6rem', sm: '0.7rem' } }}>{display.vehicleReg}</Typography>
                          ) : (
                            <Typography color="text.secondary" sx={{ fontSize: { xs: '0.55rem', sm: '0.65rem' } }}>N/A</Typography>
                          )}
                        </TableCell>

                        <TableCell sx={{ fontSize: { xs: '0.6rem', sm: '0.7rem' }, py: 1 }}>
                          {display.driverName !== 'N/A' ? (
                            <Stack direction="row" alignItems="center" spacing={0.5}>
                              <PersonIcon sx={{ fontSize: { xs: '0.6rem', sm: '0.7rem' }, color: '#6B7280' }} />
                              <Typography sx={{ fontSize: { xs: '0.6rem', sm: '0.7rem' } }}>{display.driverName}</Typography>
                            </Stack>
                          ) : (
                            <Typography color="text.secondary" sx={{ fontSize: { xs: '0.55rem', sm: '0.65rem' } }}>N/A</Typography>
                          )}
                        </TableCell>

                        <TableCell sx={{ py: 0.5 }}>
                          <StatusChip status={trip.status} />
                        </TableCell>

                        <TableCell sx={{ py: 0.5 }}>
                          <LocationDisplay
                            city={trip.originCity}
                            zipCode={trip.originZipCode}
                            province={trip.originProvince}
                            fullAddress={trip.originLocation}
                            type="origin"
                          />
                        </TableCell>

                        <TableCell sx={{ py: 0.5 }}>
                          <LocationDisplay
                            city={trip.destinationCity}
                            zipCode={trip.destinationZipCode}
                            province={trip.destinationProvince}
                            fullAddress={trip.destinationLocation}
                            type="destination"
                          />
                        </TableCell>

                        <TableCell sx={{ py: 0.5 }}>
                          {(() => {
                            const plannedDistance = trip.plannedDistanceKm;
                            const actualDistance = trip.metrics?.totalDistanceKm || trip.totalDistanceKm;
                            
                            if (actualDistance) {
                              return (
                                <Tooltip 
                                  title={`Actual: ${actualDistance} km${plannedDistance ? ` | Planned: ${plannedDistance} km` : ''}`} 
                                  arrow
                                >
                                  <Chip
                                    size="small"
                                    label={`${typeof actualDistance === 'number' ? actualDistance.toFixed(1) : actualDistance} km`}
                                    sx={{ 
                                      fontSize: { xs: '0.5rem', sm: '0.6rem' },
                                      height: { xs: 18, sm: 22 },
                                      bgcolor: '#D1FAE5',
                                      color: '#065F46',
                                      fontWeight: 600,
                                      '&:hover': { bgcolor: '#A7F3D0' }
                                    }}
                                  />
                                </Tooltip>
                              );
                            }
                            
                            if (plannedDistance) {
                              return (
                                <Chip
                                  size="small"
                                  label={`${plannedDistance} km`}
                                  variant="outlined"
                                  sx={{ 
                                    fontSize: { xs: '0.5rem', sm: '0.6rem' },
                                    height: { xs: 18, sm: 22 },
                                    color: '#6B7280'
                                  }}
                                />
                              );
                            }
                            
                            return (
                              <Typography sx={{ fontSize: { xs: '0.6rem', sm: '0.7rem' }, color: '#6B7280' }}>-</Typography>
                            );
                          })()}
                        </TableCell>

                        <TableCell sx={{ fontSize: { xs: '0.6rem', sm: '0.7rem' }, py: 0.5 }}>
                          {trip.plannedStartDate 
                            ? dayjs(trip.plannedStartDate).format('DD MMM YYYY')
                            : '-'}
                        </TableCell>

                        <TableCell sx={{ py: 0.5 }}>
                          <Box display="flex" gap={0.25} flexWrap="wrap">
                            {display.canStart && (
                              <Tooltip title="Start Trip" arrow>
                                <IconButton 
                                  size="small" 
                                  color="success" 
                                  onClick={() => handleStartTrip(trip)} 
                                  sx={{ p: { xs: 0.25, sm: 0.5 } }}
                                >
                                  <PlayArrowIcon sx={{ fontSize: { xs: '0.7rem', sm: '0.9rem' } }} />
                                </IconButton>
                              </Tooltip>
                            )}

                            {display.canEnd && (
                              <Tooltip title="End Trip" arrow>
                                <IconButton 
                                  size="small" 
                                  color="error" 
                                  onClick={() => handleOpenEndDialog(trip)} 
                                  sx={{ p: { xs: 0.25, sm: 0.5 } }}
                                >
                                  <StopIcon sx={{ fontSize: { xs: '0.7rem', sm: '0.9rem' } }} />
                                </IconButton>
                              </Tooltip>
                            )}

                            {display.canReport && (
                              <Tooltip title="Add Notice" arrow>
                                <IconButton 
                                  size="small" 
                                  color="warning" 
                                  onClick={() => handleOpenNoticeWizard(trip)} 
                                  sx={{ p: { xs: 0.25, sm: 0.5 } }}
                                >
                                  <WarningIcon sx={{ fontSize: { xs: '0.7rem', sm: '0.9rem' } }} />
                                </IconButton>
                              </Tooltip>
                            )}

                            <Tooltip title="View Details" arrow>
                              <IconButton 
                                size="small" 
                                color="primary" 
                                onClick={() => handleViewTrip(trip)} 
                                sx={{ p: { xs: 0.25, sm: 0.5 } }}
                              >
                                <ViewIcon sx={{ fontSize: { xs: '0.7rem', sm: '0.9rem' } }} />
                              </IconButton>
                            </Tooltip>

                            {display.canEdit && (
                              <Tooltip title="Edit Trip" arrow>
                                <IconButton 
                                  size="small" 
                                  color="secondary" 
                                  onClick={() => handleEditTrip(trip)} 
                                  sx={{ p: { xs: 0.25, sm: 0.5 } }}
                                >
                                  <EditIcon sx={{ fontSize: { xs: '0.7rem', sm: '0.9rem' } }} />
                                </IconButton>
                              </Tooltip>
                            )}

                            {display.canMetrics && (
                              <Tooltip title="Trip Metrics" arrow>
                                <IconButton 
                                  size="small" 
                                  color="info" 
                                  onClick={() => handleOpenMetrics(trip)} 
                                  sx={{ p: { xs: 0.25, sm: 0.5 } }}
                                >
                                  <DashboardIcon sx={{ fontSize: { xs: '0.7rem', sm: '0.9rem' } }} />
                                </IconButton>
                              </Tooltip>
                            )}

                            {display.canFinalize && (
                              <Tooltip title="Finalize Trip" arrow>
                                <IconButton 
                                  size="small" 
                                  color="success" 
                                  onClick={() => handleFinalizeTrip(trip)} 
                                  sx={{ p: { xs: 0.25, sm: 0.5 } }}
                                >
                                  <CheckCircleIcon sx={{ fontSize: { xs: '0.7rem', sm: '0.9rem' } }} />
                                </IconButton>
                              </Tooltip>
                            )}

                            {display.canCancel && (
                              <Tooltip title="Cancel Trip" arrow>
                                <IconButton 
                                  size="small" 
                                  color="warning" 
                                  onClick={() => setCancelTarget(trip)} 
                                  sx={{ p: { xs: 0.25, sm: 0.5 } }}
                                >
                                  <CancelIcon sx={{ fontSize: { xs: '0.7rem', sm: '0.9rem' } }} />
                                </IconButton>
                              </Tooltip>
                            )}

                            {display.canDelete && (
                              <Tooltip title="Delete Trip" arrow>
                                <IconButton 
                                  size="small" 
                                  color="error" 
                                  onClick={() => handleDeleteClick(trip)} 
                                  sx={{ p: { xs: 0.25, sm: 0.5 } }}
                                >
                                  <DeleteIcon sx={{ fontSize: { xs: '0.7rem', sm: '0.9rem' } }} />
                                </IconButton>
                              </Tooltip>
                            )}
                          </Box>
                        </TableCell>
                      </TableRow>
                    );
                  })
                )}
              </TableBody>
            </Table>
          </TableContainer>

          {trips.length > 0 && (
            <TablePagination
              component="div"
              count={pagination.total}
              page={pagination.page}
              onPageChange={(_, newPage) => fetchTrips({ page: newPage })}
              rowsPerPage={pagination.pageSize}
              onRowsPerPageChange={(event) => {
                const newSize = parseInt(event.target.value, 10);
                metricsCache.current = {};
                fetchTrips({ page: 0, size: newSize });
              }}
              rowsPerPageOptions={[5, 10, 25, 50]}
              labelRowsPerPage="Trips per page:"
              sx={{
                borderTop: '1px solid #ECECEC',
                '& .MuiTablePagination-selectLabel': { fontSize: '0.75rem' },
                '& .MuiTablePagination-displayedRows': { fontSize: '0.75rem' },
                '& .MuiTablePagination-select': { fontSize: '0.75rem' },
                '& .MuiTablePagination-actions button': { fontSize: '0.75rem' },
              }}
            />
          )}
        </Paper>

        {/* ============================================================
            END TRIP DIALOG - FIXED
            ============================================================ */}
        <Dialog
          open={endDialogOpen}
          onClose={handleCloseEndDialog}
          maxWidth="sm"
          fullWidth
        >
          <DialogTitle sx={{ fontSize: { xs: '0.9rem', sm: '1rem' } }}>
            <StopIcon sx={{ verticalAlign: 'middle', mr: 1, color: 'error.main' }} />
            End Trip
          </DialogTitle>
          <DialogContent>
            {endTripDetails && (
              <Box sx={{ mb: 2 }}>
                <Typography variant="body2" color="text.secondary" sx={{ fontSize: '0.8rem' }}>
                  <strong>Trip:</strong> {endTripDetails.tripNumber}
                </Typography>
                <Typography variant="body2" color="text.secondary" sx={{ fontSize: '0.8rem' }}>
                  <strong>Start Odometer:</strong> {endTripDetails.actualStartOdometer?.toFixed(2) || 'N/A'} km
                </Typography>
                <Typography variant="body2" color="text.secondary" sx={{ fontSize: '0.8rem' }}>
                  <strong>Status:</strong> {endTripDetails.status}
                </Typography>
              </Box>
            )}
            
            {error && (
              <Alert 
                severity="error" 
                sx={{ mb: 2, borderRadius: '12px', fontSize: '0.75rem', whiteSpace: 'pre-line' }}
                onClose={() => setError(null)}
              >
                {error}
              </Alert>
            )}
            
            <TextField
              autoFocus
              margin="dense"
              label="End Odometer (km)"
              type="number"
              fullWidth
              value={endOdometer}
              onChange={(e) => {
                setEndOdometer(e.target.value);
                setError(null);
              }}
              helperText={endTripDetails?.actualStartOdometer 
                ? `Must be greater than ${endTripDetails.actualStartOdometer.toFixed(2)} km` 
                : 'Enter the ending odometer reading'}
              error={!!error && !error.includes('cannot be less')}
              inputProps={{ 
                step: '0.01', 
                min: endTripDetails?.actualStartOdometer || 0 
              }}
              sx={{ '& .MuiInputLabel-root': { fontSize: '0.8rem' } }}
            />
          </DialogContent>
          <DialogActions sx={{ p: 2 }}>
            <Button 
              onClick={handleCloseEndDialog} 
              size="small" 
              sx={{ fontSize: { xs: '0.7rem', sm: '0.8rem' } }}
              disabled={endingTrip}
            >
              Cancel
            </Button>
            <Button
              onClick={handleEndTripConfirm}
              variant="contained"
              color="error"
              disabled={endingTrip || !endOdometer}
              size="small"
              sx={{ 
                fontSize: { xs: '0.7rem', sm: '0.8rem' },
                '&:hover': { bgcolor: '#DC2626' }
              }}
            >
              {endingTrip ? <CircularProgress size={18} /> : 'End Trip'}
            </Button>
          </DialogActions>
        </Dialog>

        {/* Modals */}
        {showCreateModal && (
          <TripForm
            open={showCreateModal}
            mode="create"
            onClose={() => setShowCreateModal(false)}
            onSuccess={handleModalClose(() => setShowCreateModal(false))}
          />
        )}

        {showEditModal && selectedTrip && (
          <TripForm
            open={showEditModal}
            mode="edit"
            initialData={selectedTrip}
            onClose={() => setShowEditModal(false)}
            onSuccess={handleModalClose(() => setShowEditModal(false))}
          />
        )}

        {showMetricsModal && selectedTrip && (
          <TripMetricsForm
            open={showMetricsModal}
            tripId={selectedTrip.id}
            tripData={selectedTrip}
            onClose={() => setShowMetricsModal(false)}
            onSuccess={handleMetricsSuccess}
          />
        )}

        {showDetailsModal && selectedTrip && (
          <TripDetails
            open={showDetailsModal}
            tripId={selectedTrip.id}
            onClose={() => setShowDetailsModal(false)}
            onUpdate={() => {
              metricsCache.current = {};
              fetchTrips({ page: pagination.page });
            }}
          />
        )}

        {showNoticeWizard && selectedTripForNotice && (
          <TripNoticeWizard
            open={showNoticeWizard}
            onClose={handleCloseNoticeWizard}
            trip={selectedTripForNotice}
            onSuccess={() => {
              showNotification('Notice submitted successfully!', 'success');
              handleCloseNoticeWizard();
            }}
          />
        )}

        {/* Delete Dialog */}
        <Dialog
          open={deleteDialogOpen}
          onClose={handleDeleteCancel}
          maxWidth="sm"
          fullWidth
        >
          <DialogTitle sx={{ fontSize: { xs: '0.9rem', sm: '1rem' } }}>
            <DeleteIcon sx={{ verticalAlign: 'middle', mr: 1, color: 'error.main' }} />
            Delete Trip
          </DialogTitle>
          <DialogContent>
            <DialogContentText sx={{ fontSize: { xs: '0.8rem', sm: '0.9rem' } }}>
              Delete trip <strong>{deleteTarget?.tripNumber}</strong>? This permanently removes the trip and
              cannot be undone. Only Draft and Planned trips can be deleted - use Cancel for trips that have
              already progressed.
            </DialogContentText>
          </DialogContent>
          <DialogActions sx={{ p: 2 }}>
            <Button 
              onClick={handleDeleteCancel} 
              size="small" 
              sx={{ fontSize: { xs: '0.7rem', sm: '0.8rem' } }}
            >
              Cancel
            </Button>
            <Button
              onClick={handleDeleteConfirm}
              variant="contained"
              color="error"
              disabled={deleting}
              size="small"
              sx={{ fontSize: { xs: '0.7rem', sm: '0.8rem' } }}
            >
              {deleting ? <CircularProgress size={18} /> : 'Delete'}
            </Button>
          </DialogActions>
        </Dialog>

        {/* Cancel Trip Dialog */}
        <Dialog
          open={Boolean(cancelTarget)}
          onClose={() => !cancelling && setCancelTarget(null)}
          maxWidth="sm"
          fullWidth
        >
          <DialogTitle sx={{ fontSize: { xs: '0.9rem', sm: '1rem' } }}>
            <CancelIcon sx={{ verticalAlign: 'middle', mr: 1, color: 'warning.main' }} />
            Cancel Trip
          </DialogTitle>
          <DialogContent>
            <DialogContentText sx={{ fontSize: { xs: '0.8rem', sm: '0.9rem' } }}>
              Cancel trip <strong>{cancelTarget?.tripNumber}</strong>
              {cancelTarget?.status ? ` (currently ${STATUS_CONFIG[cancelTarget.status]?.label || cancelTarget.status})` : ''}?
              The trip and its history are kept, but it can no longer be started, ended or edited.
            </DialogContentText>
          </DialogContent>
          <DialogActions sx={{ p: 2 }}>
            <Button
              onClick={() => setCancelTarget(null)}
              size="small"
              disabled={cancelling}
              sx={{ fontSize: { xs: '0.7rem', sm: '0.8rem' } }}
            >
              Keep Trip
            </Button>
            <Button
              onClick={handleCancelTripConfirm}
              variant="contained"
              color="warning"
              disabled={cancelling}
              size="small"
              sx={{ fontSize: { xs: '0.7rem', sm: '0.8rem' } }}
            >
              {cancelling ? <CircularProgress size={18} /> : 'Cancel Trip'}
            </Button>
          </DialogActions>
        </Dialog>
      </Box>
    </Box>
  );
}

export default TripList;
